function signedPercent(value) {
  if (!Number.isFinite(value)) return "—";
  if (Math.abs(value) < 0.05) return "0.0% aligned";
  const magnitude = Math.abs(value).toFixed(1);
  return value > 0 ? `+${magnitude}% above` : `−${magnitude}% below`;
}

export function sellerMarkupRange(match, marketRow) {
  if (!match || !marketRow || match.comparisonEligible === false) return null;
  const median = Number(marketRow.median || 0);
  const minPrice = Number(match.minUnitPrice || 0);
  const maxPrice = Number(match.maxUnitPrice || 0);
  if (!(median > 0) || !(minPrice > 0) || !(maxPrice > 0)) return null;

  const min = ((minPrice / median) - 1) * 100;
  const max = ((maxPrice / median) - 1) * 100;
  return { min, max, median, minPrice, maxPrice };
}

export function formatSellerMarkupRange(range) {
  if (!range) return "Not comparable";
  if (Math.abs(range.max - range.min) < 0.05) return signedPercent(range.min);
  return `${signedPercent(range.min)} to ${signedPercent(range.max)}`;
}

export function sellerMarkupTone(range) {
  if (!range) return "neutral";
  if (range.min >= 15) return "high";
  if (range.min > 2) return "above";
  if (range.max <= -5) return "below";
  return "aligned";
}
